head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS70017";
scwin.searchType1 = null;
scwin.searchType2 = null;
scwin.searchType3 = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — formKey, keyValue, returnKey

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.searchType1 = $c.util.getComponent('searchType1');
        scwin.searchType2 = $c.util.getComponent('searchType2');
        scwin.searchType3 = $c.util.getComponent('searchType3');
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70017.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_formKey", fn: function () { return String(String((dma_pageContext.get("formKey") ?? ""))); } },
        { childId: "ipt_keyValue", fn: function () { return String(String((dma_pageContext.get("keyValue") ?? ""))); } },
        { childId: "ipt_returnKey", fn: function () { return String(String((dma_pageContext.get("returnKey") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(disclosurecommon#searchmapppopinfo vs disclosurecommon#showdataalertmsg) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_type1_onclick
 * @description 「1」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_type1_onclick = function(e){
    try {
        scwin.chgSearchType('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70017.ipt_type1_onclick' }); }
};

/**
 * @method
 * @name ipt_type2_onclick
 * @description 「2」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_type2_onclick = function(e){
    try {
        scwin.chgSearchType('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70017.ipt_type2_onclick' }); }
};

/**
 * @method
 * @name ipt_type3_onclick
 * @description 「3」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_type3_onclick = function(e){
    try {
        scwin.chgSearchType('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70017.ipt_type3_onclick' }); }
};

/**
 * @method
 * @name ipt_button1_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_button1_onclick = async function(e){
    try {
        await scwin.goZipCode()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70017.ipt_button1_onclick' }); }
};

/**
 * @method
 * @name ipt_button2_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_button2_onclick = async function(e){
    try {
        await scwin.otherZipCodeChk()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70017.ipt_button2_onclick' }); }
};

/**
 * @method
 * @name grd_resultVo_oncellclick
 * @description grd_resultVo 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultVo_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultVo');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultVo */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.selected(r["selectCode"], r["selectCodeName"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultVo.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goZipCode
 * @description go Zip Code 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goZipCode = async function () {
    const sbmOptions = {
        id: "tx_goZipCode",
        method: "post",
        action: "/discls/disclosureCommon.do",
        ref: "dma_goZipCodeReq",
        target: "dlt_resultVo=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selected
 * @description selected 처리
 * @param {*} selectCode selectCode
 * @param {*} selectName selectName
 * @returns {void}
 * @hidden N
 */
scwin.selected = function (selectCode, selectName) {
    const code = selectCode;
    const name = $c.str.trim(selectName);
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setSelectedData === 'function' ? (scwin.openerScwin()).fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, code) : void 0), $c.win.closePopup([(String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, code]));
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setPopupDataValue === 'function' ? (scwin.openerScwin()).fn_setPopupDataValue('') : void 0), $c.win.closePopup(['']));
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setPopupDataValue === 'function' ? (scwin.openerScwin()).fn_setPopupDataValue(name) : void 0), $c.win.closePopup([name]));
    $c.win.closePopup();
};

/**
 * @method
 * @name specialWord
 * @description special Word 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.specialWord = function (str) {
    const reg = /%/;
    if (str == null || str === "") {
        return false;
    }
    if (reg.test(str)) {
        return true;
    }
};

/**
 * @method
 * @name checkValues
 * @description check Values 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValues = async function () {
    if (($c.util.getComponent('ipt_type2').getValue() != null && String($c.util.getComponent('ipt_type2').getValue()) !== '') === true) {
        $c.util.getComponent('dma_goZipCodeReq').set('searchWord', $c.util.getComponent('ipt_road1').getValue());
        if (($c.util.getComponent('ipt_building1').getValue() == null ? '' : String($c.util.getComponent('ipt_building1').getValue())) === '') {
            await $c.win.alert('검색할 건물명을 입력해 주세요.');
            return false;
        } else {
            if ($c.util.getComponent('ipt_building1').getValue().length < 2) {
                await $c.win.alert('건물명은 두글자 이상 입력되어야 합니다.');
                return false;
            } else {
                if (scwin.specialWord($c.util.getComponent('ipt_building1').getValue()) || scwin.specialWord($c.util.getComponent('dma_goZipCodeReq').get('searchWord'))) {
                    await $c.win.alert('%는 사용 할 수 없습니다.');
                    return false;
                } else {
                    return true;
                }
            }
        }
    } else {
        if (($c.util.getComponent('ipt_type1').getValue() != null && String($c.util.getComponent('ipt_type1').getValue()) !== '') === true) {
            $c.util.getComponent('dma_goZipCodeReq').set('searchWord', $c.util.getComponent('ipt_road').getValue());
            if ($c.util.getComponent('dma_goZipCodeReq').get('searchWord')=== '') {
                await $c.win.alert('검색할 도로명을 입력해 주세요.');
                return false;
            } else {
                if ($c.util.getComponent('dma_goZipCodeReq').get('searchWord').length < 2) {
                    await $c.win.alert('도로명은 두글자 이상 입력되어야 합니다.');
                    return false;
                } else {
                    if (scwin.specialWord($c.util.getComponent('dma_goZipCodeReq').get('searchWord')) || scwin.specialWord($c.util.getComponent('ipt_building').getValue())) {
                        await $c.win.alert('%는 사용 할 수 없습니다.');
                        return false;
                    } else {
                        return true;
                    }
                }
            }
        } else {
            await $c.win.alert('검색조건을 선택하세요.');
            return false;
        }
    }
};

/**
 * @method
 * @name goZipCode
 * @description go Zip Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goZipCode = async function () {
    if (await scwin.checkValues() === true) {
        $c.util.getComponent('dma_goZipCodeReq').set('method', "searchCommonPop");
        $c.util.getComponent('dma_goZipCodeReq').set('searchYn', "Y");
        await scwin.tx_goZipCode();
    } else {
        if ($c.util.getComponent('ipt_type1').getValue()=== '2') {
            $c.util.getComponent("ipt_building1").focus();
        } else {
            if ($c.util.getComponent('ipt_type1').getValue()=== '1') {
                searchWord.focus();
            }
        }
    }
};

/**
 * @method
 * @name chgSearchType
 * @description chg Search Type 처리
 * @param {*} searchType searchType
 * @returns {void}
 * @hidden N
 */
scwin.chgSearchType = function (searchType) {
    const divType1 = $c.util.getComponent('searchType1');
    const divType2 = $c.util.getComponent('searchType2');
    const divType3 = $c.util.getComponent('searchType3');
    if (searchType === '1') {
        $c.util.getComponent("ipt_road").setValue("");
        $c.util.getComponent("ipt_building1").setValue("");
        scwin.searchType1.setStyle("display", "");
        scwin.searchType2.setStyle("display", "none");
        scwin.searchType3.setStyle("display", "none");
        $c.util.getComponent('ipt_button1').setStyle("display", "");
        $c.util.getComponent('ipt_button2').setStyle("display", "none");
    } else {
        if (searchType === '2') {
            $c.util.getComponent("ipt_road1").setValue("");
            $c.util.getComponent("ipt_building").setValue("");
            scwin.searchType1.setStyle("display", "none");
            scwin.searchType2.setStyle("display", "");
            scwin.searchType3.setStyle("display", "none");
            $c.util.getComponent('ipt_button1').setStyle("display", "");
            $c.util.getComponent('ipt_button2').setStyle("display", "none");
        } else {
            if (searchType === '3') {
                scwin.searchType1.setStyle("display", "none");
                scwin.searchType2.setStyle("display", "none");
                scwin.searchType3.setStyle("display", "");
                $c.util.getComponent('ipt_button1').setStyle("display", "none");
                $c.util.getComponent('ipt_button2').setStyle("display", "");
                $("tbody").empty();
                $("tbody").append('<tr><td colspan="2">데이터가 존재하지 않습니다.</td></tr>');
            }
        }
    }
};

/**
 * @method
 * @name otherZipCodeChk
 * @description other Zip Code Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.otherZipCodeChk = async function () {
    if (($c.util.getComponent('ipt_zipNo').getValue() == null ? '' : String($c.util.getComponent('ipt_zipNo').getValue())) === '' || $c.util.getComponent('ipt_zipNo').getValue() == null) {
        await $c.win.alert("우편번호를 입력해 주세요.");
        $c.util.getComponent("ipt_zipNo").focus();
        return;
    }
    if (/[^0123456789]/g.test($c.util.getComponent('ipt_zipNo').getValue())) {
        if ($c.util.getComponent('ipt_zipNo').getValue() !== "-") {
            await $c.win.alert("우편번호는 숫자 또는 -만 가능합니다.");
            $c.util.getComponent("ipt_zipNo").focus();
            return;
        }
    }
    if (($c.util.getComponent('ipt_searchWord3').getValue() == null ? '' : String($c.util.getComponent('ipt_searchWord3').getValue())) === '' || $c.util.getComponent('ipt_searchWord3').getValue() == null) {
        await $c.win.alert("주소를 입력해 주세요.");
        $c.util.getComponent("ipt_searchWord3").focus();
        return;
    }
    scwin.selected($c.util.getComponent('ipt_zipNo').getValue(), $c.util.getComponent('ipt_searchWord3').getValue());
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
